<section class="tos-records" aria-labelledby="tos-records-title">
  <h2 id="tos-records-title">Record TOS</h2>
  <div id="tos-records-table" aria-live="polite"><p>Calcolo dei record in corso…</p></div>
</section>
<style>
.tos-records{margin:28px 0;padding:20px;border:1px solid #8793a744;border-radius:18px}.tos-records .records-filters{display:flex;flex-wrap:wrap;gap:16px;margin:16px 0}.tos-records select{padding:10px;max-width:100%;background:inherit;color:inherit;border:1px solid #8793a7;border-radius:8px}.tos-records .records-scroll{overflow-x:auto}.tos-records table{border-collapse:collapse;width:100%;min-width:640px}.tos-records th,.tos-records td{text-align:left;vertical-align:top;padding:14px 10px;border-bottom:1px solid #8793a744}.tos-records th{font-weight:700}.tos-records caption{text-align:left;font-weight:700;font-size:1.2rem;padding:16px 0}.tos-records td:first-child{width:25%}.tos-records td:nth-child(2){font-weight:700}.tos-records li{margin:0 0 14px}.tos-records ul{padding-left:18px;margin:0}.tos-records summary{cursor:pointer}.tos-records a{color:inherit;text-decoration:underline}.tos-records small{display:block;margin-top:4px}
</style>
<script src="/records-table.js" defer></script>
